import { join } from 'node:path';
import { sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { pool } from './database';

// Arbitrary constant shared by every process that migrates this database.
const MIGRATION_LOCK = 4_172_031;

// Generated by `npm run db:generate`; the build copies them next to the compiled code.
const MIGRATIONS_FOLDER = join(__dirname, 'migrations');

/**
 * Applies pending migrations, all in one transaction. Safe to call from several processes
 * at once: an advisory lock serializes them.
 */
export async function applyMigrations(): Promise<void> {
  const client = await pool.connect();
  const connection = drizzle({ client });
  try {
    await connection.execute(sql`SELECT pg_advisory_lock(${MIGRATION_LOCK})`);
    await migrate(connection, { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await connection
      .execute(sql`SELECT pg_advisory_unlock(${MIGRATION_LOCK})`)
      .catch(() => undefined);
    client.release();
  }
}
